  if (item.check === "configuration-path") return "\u5DF2\u6709\u914D\u7F6E\u6A21\u578B\u8BC1\u636E\uFF1B\u4E0D\u662F\u672C\u6B21\u771F\u5B9E\u4E1A\u52A1\u8DEF\u5F84\u3001\u5F53\u524D\u8FDE\u63A5\u7ED3\u679C\u6216\u6545\u969C\u56E0\u679C\u94FE\u3002";
  if (item.executed === false) return "\u672C\u9879\u660E\u786E\u672A\u6267\u884C\uFF1B\u7F3A\u5931\u7ED3\u679C\u4E0D\u89E3\u91CA\u4E3A\u6B63\u5E38\u3002";
  return "\u4EC5\u4FDD\u7559\u672C\u9879\u5DF2\u4FDD\u5B58\u4E8B\u5B9E\uFF1B\u672A\u8BB0\u5F55\u72EC\u7ACB\u6458\u8981\uFF0C\u4E0D\u751F\u6210\u65B0\u5224\u65AD\u3002";
}
function factDetail(evidence) {
